// Universal Multi-Source JSON Field Mapper
return $input.all().map((item) => {
  const raw = item.json.body || item.json || {};
  return {
    json: {
      Timestamp: new Date().toISOString().slice(0, 19).replace('T', ' ') + ' UTC',
      Source_Trigger: raw.headers ? 'Webhook POST Trigger' : 'Scheduled Cloud Trigger',
      Record_Title: raw.title || raw.subject || raw.template || '08_Universal_JSON_Template_Pack.json (Verified)',
      Owner_Email: raw.email || raw.owner || 'ops@company-domain.com',
      Status: '✓ Imported & Active on Self-Hosted n8n Cloud'
    }
  };
});
